class MultiLogger:
    def __init__(self, *loggers: structlog.stdlib.BoundLogger):
        self._loggers = loggers

    def _log(self, level: str, *args: Any, **kwargs: Any):
        for lgr in self._loggers:
            getattr(lgr, level)(*args, **kwargs)

    def debug(self, *a, **k):
        self._log("debug", *a, **k)

    def info(self, *a, **k):
        self._log("info", *a, **k)

    def warning(self, *a, **k):
        self._log("warning", *a, **k)

    def warn(self, *a, **k):
        self._log("warn", *a, **k)

    def error(self, *a, **k):
        self._log("error", *a, **k)

    def exception(self, *a, **k):
        # Mirror stdlib `Logger.exception`: log at error level with the active
        # traceback. Without this method a caller reaching for `log.exception(...)`
        # -- the natural thing to write inside an `except` block -- would raise
        # AttributeError from inside the handler and take the caller down with it.
        k.setdefault("exc_info", True)
        self._log("error", *a, **k)

